class MinHeap {
  constructor() {
    this.heap = [];
  }

  // Parent index: (i - 1) / 2
  // Left child: 2 * i + 1
  // Right child: 2 * i + 2

  peek() {
    return this.heap[0];
  }

  size() {
    return this.heap.length;
  }

  insert(value) {
    this.heap.push(value);
    this._bubbleUp(this.heap.length - 1);
  }

  extractMin() {
    if (this.heap.length === 0) return null;
    const min = this.heap[0];
    const last = this.heap.pop();
    if (this.heap.length > 0) {
      this.heap[0] = last;
      this._sinkDown(0);
    }
    return min;
  }

  _bubbleUp(index) {
    while (index > 0) {
      const parentIndex = Math.floor((index - 1) / 2);
      if (this.heap[parentIndex] <= this.heap[index]) break;
      [this.heap[parentIndex], this.heap[index]] = 
        [this.heap[index], this.heap[parentIndex]];
      index = parentIndex;
    }
  }

  _sinkDown(index) {
    const length = this.heap.length;
    while (true) {
      let smallest = index;
      const left = 2 * index + 1;
      const right = 2 * index + 2;

      if (left < length && this.heap[left] < this.heap[smallest]) {
        smallest = left;
      }
      if (right < length && this.heap[right] < this.heap[smallest]) {
        smallest = right;
      }
      if (smallest === index) break;
      [this.heap[smallest], this.heap[index]] = 
        [this.heap[index], this.heap[smallest]];
      index = smallest;
    }
  }
}

class MaxHeap {
  constructor() {
    this.heap = [];
  }

  insert(value) {
    this.heap.push(value);
    this._bubbleUp(this.heap.length - 1);
  }

  extractMax() {
    if (this.heap.length === 0) return null;
    const max = this.heap[0];
    const last = this.heap.pop();
    if (this.heap.length > 0) {
      this.heap[0] = last;
      this._sinkDown(0);
    }
    return max;
  }

  _bubbleUp(index) {
    while (index > 0) {
      const parentIndex = Math.floor((index - 1) / 2);
      if (this.heap[parentIndex] >= this.heap[index]) break;
      [this.heap[parentIndex], this.heap[index]] = 
        [this.heap[index], this.heap[parentIndex]];
      index = parentIndex;
    }
  }

  _sinkDown(index) {
    const length = this.heap.length;
    while (true) {
      let largest = index;
      const left = 2 * index + 1;
      const right = 2 * index + 2;
      if (left < length && this.heap[left] > this.heap[largest]) largest = left;
      if (right < length && this.heap[right] > this.heap[largest]) largest = right;
      if (largest === index) break;
      [this.heap[largest], this.heap[index]] = 
        [this.heap[index], this.heap[largest]];
      index = largest;
    }
  }

  // Build heap from array in O(n)
  static heapify(arr) {
    const heap = new MaxHeap();
    heap.heap = arr;
    for (let i = Math.floor(arr.length / 2) - 1; i >= 0; i--) {
      heap._sinkDown(i);
    }
    return heap;
  }
}

function findKthLargest(nums, k) {
  const minHeap = new MinHeap();

  for (const num of nums) {
    minHeap.insert(num);
    if (minHeap.size() > k) {
      minHeap.extractMin(); // evict smallest of the K+1
    }
  }
  return minHeap.peek();
}

// Using built-in JavaScript (sort):
function findKthLargestSort(nums, k) {
  nums.sort((a, b) => b - a);
  return nums[k - 1];
}

// Time: O(n log k) with heap, O(n log n) with sort
// Space: O(k) with heap, O(1) or O(n) with sort

function topKFrequent(nums, k) {
  // Step 1: Count frequencies
  const freq = {};
  for (const num of nums) {
    freq[num] = (freq[num] || 0) + 1;
  }

  // Step 2: Min-heap on frequency
  const heap = new MinHeap();
  heap.compare = (a, b) => a.freq - b.freq; // customize comparator

  for (const [num, count] of Object.entries(freq)) {
    heap.insert({ num, freq: count });
    if (heap.size() > k) heap.extractMin();
  }

  // Step 3: Extract result
  return heap.heap.map(item => Number(item.num));
}

