function leastInterval(tasks, n) {
  const freq = {};
  for (const task of tasks) {
    freq[task] = (freq[task] || 0) + 1;
  }

  // Max-heap on frequency (negate for JS min-heap)
  const maxHeap = [];
  for (const count of Object.values(freq)) {
    maxHeap.push(-count);
  }
  maxHeap.sort((a, b) => a - b); // initial heapify

  let time = 0;
  const queue = []; // [remainingCount, readyTime]

  while (maxHeap.length || queue.length) {
    time++;
    if (maxHeap.length) {
      let count = maxHeap.pop() + 1; // remove neg
      if (count < 0) {
        queue.push([count, time + n]);
      }
    }
    if (queue.length && queue[0][1] <= time) {
      maxHeap.push(queue.shift()[0]);
    }
  }
  return time;
}

// Cleaner with MinHeap class (min-heap on readyTime):
function leastIntervalClean(tasks, n) {
  const freq = {};
  for (const t of tasks) freq[t] = (freq[t] || 0) + 1;
  const heap = Object.values(freq).sort((a, b) => b - a); // max-heap by negative ordering
  const queue = [];
  let time = 0;
  while (heap.length || queue.length) {
    time++;
    if (heap.length) {
      let cnt = heap.pop() - 1;
      if (cnt > 0) queue.push([cnt, time + n]);
    }
    if (queue.length && queue[0][1] === time) {
      heap.push(queue.shift()[0]);
    }
  }
  return time;
}
